use canvas_core::{preview_error::{self,DEFAULT_DESCRIPTION},error_archive::{ErrorArchive as A,Limits,Error},remote_error::RemoteErrorLeaf as L,payload_codec::Value as V,binary_plist,human_readable_error::{extract_encoded_with,ARCHIVE_KEY},service_reply_error::ServiceReplyError,service_response::send_service_response_binary,service_reply_failure::{classify_service_observed_data_with,ReplyRepresentation,ServiceReplyFailure},settings_xpc::XpcValue};use std::collections::BTreeMap;
fn leaf(high:Option<&str>,low:Option<&str>)->A{let mut fields=BTreeMap::from([("errorType".into(),V::String("leaf".into()))]);if let Some(v)=high{fields.insert("highValueTitle".into(),V::String(v.into()));}if let Some(v)=low{fields.insert("lowValueTitle".into(),V::String(v.into()));}A::Leaf(L::from_dictionary(&fields).unwrap())}
fn serializable_description_preserves_optional_empty_and_fixed_fallback(){for(high,low,expected)in[(Some(""),Some("low"),""),(None,Some(""),""),(Some("high 🪨"),Some("low"),"high 🪨"),(None,Some("low"),"low"),(None,None,DEFAULT_DESCRIPTION)]{let archive=leaf(high,low);let e=preview_error::from_archive(&archive).unwrap();assert_eq!(e.domain,"com.apple.Previews");assert_eq!(e.code,-1);assert_eq!(e.user_info.len(),2);assert_eq!(e.user_info["NSLocalizedDescription"],V::String(expected.into()));assert_eq!(extract_encoded_with(&e.user_info,A::from_dictionary),Some(archive));}}
fn wrapper_high_title_can_come_from_cause_before_main_low_title(){let archive=A::Wrapper{main:Box::new(leaf(None,Some("main low"))),underlying:Box::new(leaf(Some(""),Some("cause low")))};let e=preview_error::from_archive(&archive).unwrap();assert_eq!(e.user_info["NSLocalizedDescription"],V::String("".into()));let V::Dictionary(encoded)=&e.user_info[ARCHIVE_KEY]else{panic!()};assert_eq!(A::from_dictionary(encoded).unwrap(),archive);}
fn bounded_archive_build_composes_with_complete_binary_service_error(){let archive=A::Wrapper{main:Box::new(leaf(Some("owned"),None)),underlying:Box::new(leaf(None,None))};assert_eq!(preview_error::from_archive_with_limits(&archive,Limits{nodes:2,depth:64}),Err(Error::Limit));let expected=preview_error::from_archive(&archive).unwrap();let mut wire=BTreeMap::new();assert_eq!(send_service_response_binary(true,None,Some(expected.clone()),&mut wire,Some,|_|()),Some(()));let XpcValue::Data(bytes)=&wire["data"]else{panic!()};let(p,e)=classify_service_observed_data_with(Some(bytes),ReplyRepresentation::SerializedData,binary_plist::decode,||panic!());assert!(p.is_none());let Some(ServiceReplyFailure::Remote(restored))=e else{panic!()};assert_eq!(restored,expected);assert_eq!(extract_encoded_with(&restored.user_info,A::from_dictionary),Some(archive));}

fn main(){serializable_description_preserves_optional_empty_and_fixed_fallback();wrapper_high_title_can_come_from_cause_before_main_low_title();bounded_archive_build_composes_with_complete_binary_service_error();println!("WASI preview NSError value builder and binary service round trip passed");}
